CREATE TABLE public.agency_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, name text NOT NULL CHECK (char_length(name) BETWEEN 2 AND 120), city text NOT NULL CHECK (char_length(city) BETWEEN 2 AND 80), country text NOT NULL, specialty text NOT NULL CHECK (char_length(specialty) BETWEEN 2 AND 300), created_at timestamptz NOT NULL DEFAULT now(), CHECK (country='United States' OR (country='United Arab Emirates' AND city IN ('Dubai','Abu Dhabi')))); GRANT SELECT ON public.agency_profiles TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.agency_profiles TO authenticated; GRANT ALL ON public.agency_profiles TO service_role; ALTER TABLE public.agency_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY "Public agency directory" ON public.agency_profiles FOR SELECT TO anon,authenticated USING (true); CREATE POLICY "Create own free agency" ON public.agency_profiles FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid()); CREATE POLICY "Update own agency" ON public.agency_profiles FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid()); CREATE POLICY "Delete own agency" ON public.agency_profiles FOR DELETE TO authenticated USING (user_id=auth.uid());